<script>
  import { getIcon, loadIcon } from '@iconify/svelte'
  import { toStyleString } from '@splendidlabz/utils'
  import { onMount } from 'svelte'

  export let icon
  export let style = ''

  if (typeof style === 'object') style = toStyleString(style)
  if (!icon) throw new Error('icon property is required')

  let iconData
  let innerHTML
  const attributes = {
    class: `${icon.split(':')[1]}`,
    role: 'img',
    xmlns: 'http://www.w3.org/2000/svg',
    width: '1em',
    height: '1em',
    style,
    ...$$restProps,
  }

  // If there is an icon set, we use Iconify.
  // This stores the icon in localStorage after loading it for the first time. Subsequent loads will use the localStorage cached version.

  // Reads the cache after hydration so the first render matches the server
  // If icon is not in cache, loads the icon from Iconify
  onMount(async _ => (iconData = getIcon(icon) || (await loadIcon(icon))))

  $: if (iconData) {
    attributes.viewBox = `0 0 ${iconData.width} ${iconData.height}`
    innerHTML = iconData.body
  }
</script>

{#if innerHTML}
  <!-- eslint-disable-next-line svelte/no-at-html-tags -->
  <svg aria-hidden="true" {...attributes}> {@html innerHTML} </svg>
{:else}
  <svg aria-hidden="true" {...attributes} />
{/if}
